static void z_vrfy_timer_View(void)
{
	/* Verify k_timer_init with NULL timer */
	ztest_set_fault_valid(true);
	timer_init(NULL, NULL, NULL);
}

/**
 * @brief Test k_timer_init() API
 *
 * @details Create a thread and set k_timer_init() input to NULL
 *
 * @ingroup kernel_timer_tests
 *
 * @see k_timer_init()
 */
ZTEST(timer_api_error, test_timer_init_null)
{
	if (!IS_ENABLED(CONFIG_USERSPACE)) {
		ztest_test_skip();
	}

	k_tid_t tid = k_thread_create(&tdata, tstack, STACK_SIZE,
			(k_thread_entry_t)z_vrfy_timer_View,
			NULL, NULL, NULL,
			K_PRIO_PREEMPT(THREAD_TEST_PRIORITY),
			K_INHERIT_PERMS, K_NO_WAIT);

	k_thread_join(tid, K_FOREVER);
}

static void expiry_fn(struct k_timer *timer)
{
	ARG_UNUSED(timer);
}

static void stop_fn(struct k_timer *timer)
{
	ARG_UNUSED(timer);
}

static void timer_status_sync_entry(void *p1, void *p2, void *p3)
{
	k_timer_start(&sync_timer, K_MSEC(DURATION), K_MSEC(PERIOD));
	k_msleep(TEST_TIMEOUT);
	k_timer_stop(&sync_timer);
}

/**
 * @brief Test k_timer_status_sync() API
 *
 * @details Define and initialize a timer, create a thread to start and
 * stop the timer with a delay in between. Meanwhile the main thread
 * keeps calling k_timer_status_sync() on the timer to test synchronization.
 *
 * @ingroup kernel_timer_tests
 *
 * @see k_timer_status_sync()
 */
ZTEST(timer_api_error, test_timer_status_sync)
{
	timer_init(&sync_timer, expiry_fn, stop_fn);

	k_tid_t tid = k_thread_create(&tdata, tstack, STACK_SIZE,
			(k_thread_entry_t)timer_status_sync_entry,
			NULL, NULL, NULL,
			K_PRIO_PREEMPT(THREAD_TEST_PRIORITY),
			K_INHERIT_PERMS, K_NO_WAIT);

	k_timer_status_sync(&sync_timer);

	k_thread_join(tid, K_FOREVER);
}

void *test_setup(void)
{
	k_thread_access_grant(k_current_get(), &tdata, &tstack, &mytimer, &sync_timer);

	return NULL;
}

ZTEST_SUITE(timer_api_error, NULL, test_setup, NULL, NULL, NULL);
